        {
          "quote_id": "concern_001.s3.q1"
        },
        {
          "quote_id": "concern_001.s1.q2"
        }
      ]
    },
    {
      "component_id": "concern_002",
      "text": "The Internet Transactions Act gives an online consumer the right to seek repair, replacement, refund or other remedies when the product delivered is defective, malfunctions, is lost without the consumer’s fault, or does not conform to the contract. If the consumer opts for replacement or refund, the online merchant may require the return of the original goods at no cost to the consumer, and the return must be made within a reasonable period unless the parties have agreed otherwise.",
      "evidence": [
        {
          "quote_id": "concern_002.s1.q1"
        },
        {
          "quote_id": "concern_002.s1.q2"
        }
      ]
    }
  ]
}

